    grilleSmall = grilleDepth * mbuToMm < resultingTopPlateHeight;

    //Decorator Rotations
    decoratorRotations = [[90, 0, -90], [90, 0, 90], [90, 0, 0], [90, 0, 180], [0, 180, 180], [0, 0, 0]];

